import{_ as e,o as s,c as a,a2 as r}from"./chunks/framework.SiCi1vp-.js";const g=JSON.parse('{"title":"Evaluation checklist","description":"","frontmatter":{},"headers":[],"relativePath":"evaluate.md","filePath":"evaluate.md","lastUpdated":1794071186000}'),o={name:"evaluate.md"};function n(i,t,d,l,h,c){return s(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="evaluation-checklist" tabindex="-1">Evaluation checklist <a class="header-anchor" href="#evaluation-checklist" aria-label="Permalink to &quot;Evaluation checklist&quot;">​</a></h1><p>A checklist for teams evaluating Open AgentHub on their own infrastructure: what to prepare, the steps from a fresh host to a team signing in, how long each step took when we measured it, and the limits you should know before you start. It follows the <a href="/docs/getting-started">Install</a> page; nothing here replaces it.</p><p>The times below were measured in a deliberately slow environment: an emulated virtual machine (4 vCPU, 10 GB RAM, no hardware acceleration), on release 1.20.0 for the install, the team login and the first sign-in, and on 1.19.0 for the first session and task. Treat them as upper bounds. On ordinary hardware with a fast network the quickstart itself takes about a minute.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You need</th><th>Why</th><th>Notes</th></tr></thead><tbody><tr><td>A Linux host (4 vCPU / 6 GB RAM) or a Kubernetes cluster</td><td>The hub, its database and every agent session run there</td><td>The quickstart installs a single-node k3s cluster; macOS and Windows use k3d in Docker Desktop</td></tr><tr><td>Outbound access to the k3s and Helm download sites and <code>ghcr.io</code></td><td>The installer and the images come from there</td><td>Air-gapped installs were not part of this evaluation</td></tr><tr><td>A hostname with DNS and a TLS certificate</td><td>Single sign-on and sharing need one stable HTTPS address</td><td>The certificate must be trusted by browsers. The backend also has to trust the identity provider&#39;s certificate: for a private certificate authority, put its PEM bundle in a ConfigMap and set <code>backend.trustedCaConfigMap</code> — see <a href="/docs/getting-started#move-the-quickstart-to-team-login">Move the quickstart to team login</a>. Team members&#39; browsers need that authority installed separately</td></tr><tr><td>An OIDC identity provider</td><td>One account per person; groups for Enterprise roles</td><td>Public client with PKCE, JWT access tokens for audience <code>agenthub</code>, a <code>preferred_username</code> claim, refresh tokens (<code>offline_access</code>), and a <code>groups</code> claim if you want group roles</td></tr><tr><td>The username of your first administrator</td><td><code>ee.admins</code>; nobody is an admin until one is named</td><td>Use the identity provider&#39;s <code>preferred_username</code></td></tr><tr><td>Access to your Git host</td><td>Agents clone and push with your credentials</td><td>A personal access token in Settings → Credentials, or a GitHub/GitLab OAuth app — see <a href="/docs/git">Git</a></td></tr><tr><td>A model account or your own endpoint</td><td>Agents need a model</td><td>Subscription login, an API key, or your own Messages-API-compatible endpoint — see <a href="/docs/provider-login">Provider login</a> and <a href="/docs/models">Choosing a model</a></td></tr><tr><td>For Enterprise features: a licence</td><td>Sharing, group roles, usage limits, the agent allowlist</td><td>Obtained from <strong>Settings → License → Get enterprise license</strong>; see <a href="/docs/admin">Admin</a></td></tr></tbody></table><h2 id="steps-and-measured-times" tabindex="-1">Steps and measured times <a class="header-anchor" href="#steps-and-measured-times" aria-label="Permalink to &quot;Steps and measured times&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Step</th><th>What you do</th><th>Measured (emulated VM)</th></tr></thead><tbody><tr><td>1</td><td>Install</td><td><code>curl -fsSL https://open-agenthub.github.io/install.sh | sh</code></td><td>5 min 43 s, images pinned to the release</td></tr><tr><td>2</td><td>First look</td><td>Port-forward, sign in with the generated API key</td><td>under a minute</td></tr><tr><td>3</td><td>Certificate</td><td>Create the TLS Secret for your hostname</td><td>seconds</td></tr><tr><td>4</td><td>Identity provider</td><td>Register the client, redirects and origin (<a href="/docs/getting-started#_2-sign-in">Install</a>)</td><td>depends on your provider; not measured</td></tr><tr><td>5</td><td>Team login</td><td>One <code>team-values.yaml</code> (ingress, <code>frontendOrigin</code>, <code>oidc.*</code>, <code>ee.admins</code>, and <code>backend.trustedCaConfigMap</code> for a private certificate authority), one <code>helm upgrade</code> — see <a href="/docs/getting-started#move-the-quickstart-to-team-login">Move the quickstart to team login</a></td><td>1 min 28 s, including the CA ConfigMap and the TLS Secret</td></tr><tr><td>6</td><td>First sign-in</td><td>The administrator signs in through the identity provider</td><td>17 s</td></tr><tr><td>7</td><td>Enterprise (optional)</td><td>Activate the licence under <strong>Settings → License</strong></td><td>seconds once you have a token</td></tr><tr><td>8</td><td>First session</td><td>Choose agent, billing and repository; start</td><td>the first start pulls the agent image (about 500 MB, 2 min 18 s here); later starts reuse it</td></tr><tr><td>9</td><td>First task</td><td>An interactive task that changes code, runs tests and pushes a branch</td><td>2 min from start to pushed branch with a scripted stand-in model; a real model&#39;s time depends on the task</td></tr></tbody></table><p>What can cost time, so you can avoid it:</p><ul><li><strong>Ingress class.</strong> On the quickstart cluster set <code>ingress.className=traefik</code>; the chart&#39;s default class is not the one k3s runs, and the hub is then not reachable at its hostname.</li><li><strong>An identity provider that is not reachable yet.</strong> If the backend cannot validate the identity provider, it stops with one clear error and is restarted; <code>helm upgrade --wait</code> waits until it succeeds or its timeout (5 minutes in the documented command) runs out. Make sure the provider answers from inside the cluster first, and check <code>kubectl logs -n agenthub deployment/agenthub-backend</code> early; the previous version keeps serving meanwhile.</li></ul><h2 id="the-workflow-to-try" tabindex="-1">The workflow to try <a class="header-anchor" href="#the-workflow-to-try" aria-label="Permalink to &quot;The workflow to try&quot;">​</a></h2><p>A good first evaluation, with two or three colleagues:</p><ol><li>The administrator maps identity-provider groups to <strong>admin</strong> or <strong>user</strong>, sets a monthly API budget for a group, and limits which agents may be started (<strong>Settings → Usage limits &amp; groups</strong>). Enterprise.</li><li>Create a project and share it with a reviewer as <strong>Viewer</strong>. Enterprise.</li><li>Start an <strong>Interactive</strong> session from an issue: agent, model, repository and the issue text as the task. Answer the first tool approval; <strong>Allow (don&#39;t ask again)</strong> covers that tool for the rest of the session.</li><li>The agent works on a branch and pushes it. Opening the pull request needs a token or OAuth app that allows it on your Git host.</li><li>Share the running session with a colleague as <strong>Collaborator</strong>; they find it under <strong>Shared with me</strong> and continue the conversation. Enterprise.</li><li>Switch the session&#39;s model between turns from the model menu in the session bar — see <a href="/docs/models">Choosing a model</a>.</li><li>Create a read-only link, open it in a private window, and revoke it. Enterprise.</li><li>Restrict the session&#39;s MCP servers or tools under <strong>MCP security</strong> in the <strong>Share</strong> dialog — see <a href="/docs/sharing#mcp-restrictions-for-the-whole-session">Sharing</a>. Enterprise.</li></ol><h2 id="known-limits" tabindex="-1">Known limits <a class="header-anchor" href="#known-limits" aria-label="Permalink to &quot;Known limits&quot;">​</a></h2><ul><li><strong>Enterprise licence.</strong> The checkout under <strong>Settings → License</strong> asks for payment details. There is no hosted instance to try.</li><li><strong>Tool approvals belong to the session owner.</strong> A collaborator can type into a shared session but cannot answer its approval prompts; the owner answers them, or allows a tool for the whole session.</li><li><strong>MCP restrictions have limits.</strong> Blocking single tools works for Claude, Codex and OpenCode; for Cursor and OpenClaw only whole servers can be blocked. A changed server list applies after the session restarts. The restrictions cover MCP only: they do not block network access or secrets that the agent can reach from its shell.</li><li><strong>Sessions created with the quickstart API key</strong> stay with the user <code>admin</code> after you switch to single sign-on, until an admin hands them to their owner (<a href="/docs/admin#hand-over-data-from-api-key-mode">Hand over data from API-key mode</a>).</li><li><strong>OpenClaw sessions</strong> do not appear in Slack, Telegram or Signal.</li><li><strong>The first session start is slow</strong> because the agent image is pulled on first use.</li></ul><h2 id="roles-and-editions" tabindex="-1">Roles and editions <a class="header-anchor" href="#roles-and-editions" aria-label="Permalink to &quot;Roles and editions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Community</th><th>Enterprise</th></tr></thead><tbody><tr><td>Install, single sign-on, admins named in <code>ee.admins</code></td><td>✓</td><td>✓</td></tr><tr><td>Sessions, projects, model switch, Workspace</td><td>✓</td><td>✓</td></tr><tr><td>Sharing sessions and projects, share links</td><td></td><td>✓</td></tr><tr><td>Group roles, usage limits, agent allowlist, seats</td><td></td><td>✓</td></tr><tr><td>MCP restrictions per session</td><td></td><td>✓</td></tr></tbody></table><p>Administrators see <strong>Settings → Admin</strong>; users see their own sessions, those shared with them and the projects they belong to. See <a href="/docs/admin">Admin</a> and <a href="/docs/sharing">Sharing</a>.</p>',17)])])}const m=e(o,[["render",n]]);export{g as __pageData,m as default};
